+const PRELOAD_ROUTES: Array<() => Promise<unknown>> = [
+  () => import("@/pages/dashboard"),
+  () => import("@/pages/merchant-terminal-mobile-v2"),
+  () => import("@/pages/transactions"),
+  () => import("@/pages/stock-management"),
